// --- aiuti comuni del 14 · Smista materiale (stessi criteri di 06, 07 e 08) ---
function testo(v) { return v === undefined || v === null ? '' : String(v).trim(); }
function numero(v, predefinito) { const n = Number(String(v === undefined || v === null ? '' : v).replace(',', '.')); return Number.isFinite(n) && String(v).trim() !== '' ? n : predefinito; }
function norm(v) { return testo(v).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim(); }
function siNo(v) { return ['si', 'yes', 'true', '1', 'x', 'vero', 'ok'].includes(norm(v)); }
// Taglio sicuro anche con le emoji (conta i caratteri veri, non le metà).
function taglia(s, max) { const a = Array.from(testo(s)); return a.length > max ? a.slice(0, max - 1).join('') + '…' : a.join(''); }
function idDrive(v) {
  const s = testo(v);
  if (!s) return '';
  const m = s.match(/\/(?:file\/d|folders|d)\/([A-Za-z0-9_-]{10,})/) || s.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  return /^[A-Za-z0-9_-]{10,}$/.test(s) ? s : '';
}
const MIME_CARTELLA = 'application/vnd.google-apps.folder';
// Foto che l'08 sa lavorare (la sua lista MIME_FOTO).
const MIME_FOTO = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/tiff', 'image/avif'];
// Video: stesso criterio del 07 (MIME video/* oppure estensione nota). Audio della musica: come il 07.
const ESTENSIONI_VIDEO = ['mp4', 'mov', 'm4v', 'avi', 'mkv', 'webm', 'mts', 'm2ts', '3gp', 'hevc', 'mpg', 'mpeg'];
const ESTENSIONI_AUDIO = ['mp3', 'm4a', 'wav', 'aac', 'ogg', 'oga', 'flac', 'opus'];
// Limiti scritti nel codice di 07 (reel), 06 (storie) e 08 (post, valore di serie di MAX_MB_FOTO).
const MAX_CLIP_REEL = 16;
const MAX_BYTE_CLIP = 300 * 1024 * 1024;
const MAX_BYTE_TOTALE_REEL = 800 * 1024 * 1024;
const MAX_FOTO_CAROSELLO = 10;
const MAX_BYTE_FOTO_POST = 40 * 1024 * 1024;
function estensione(nome) { const m = testo(nome).match(/\.([A-Za-z0-9]{1,5})$/); return m ? m[1].toLowerCase() : ''; }
function eCartella(f) { return !!f && f.mimeType === MIME_CARTELLA; }
function eFoto(f) { return !!f && MIME_FOTO.includes(testo(f.mimeType).toLowerCase()); }
function eHeic(f) { return !!f && /heic|heif/i.test(testo(f.mimeType) + ' ' + testo(f.name)); }
function eVideo(f) { return !!f && !eCartella(f) && (/^video\//i.test(testo(f.mimeType)) || ESTENSIONI_VIDEO.includes(estensione(f.name))); }
function eMusica(f) { return !!f && !eCartella(f) && /^musica\.[a-z0-9]{1,5}$/i.test(testo(f.name)) && (/^audio\//i.test(testo(f.mimeType)) || ESTENSIONI_AUDIO.includes(estensione(f.name))); }
function eBrief(f) { return !!f && !eCartella(f) && norm(f.name) === 'brief.txt'; }
function eSrt(f) { return !!f && !eCartella(f) && norm(f.name) === 'sottotitoli.srt'; }
// File di sistema che i computer mettono da soli: si ignorano senza dire niente.
function eSistema(f) { const n = norm(f && f.name); return n === 'desktop.ini' || n === '.ds_store' || n === 'thumbs.db' || (n.startsWith('.') && !n.startsWith('._')); }
// Appunti .txt (non brief.txt): dentro una cartella 07 e 08 li ignorano; sciolti non sono materiale.
function eAppunto(f) { const n = norm(f && f.name); return testo(f && f.mimeType).toLowerCase().startsWith('text/') && n.endsWith('.txt') && n !== 'brief.txt'; }
// File che 07 e 08 contano come clip o foto ma non lo sono: le copie «._nome» del Mac e le scorciatoie di Drive.
function eSporco(f) { return testo(f && f.name).startsWith('._') || testo(f && f.mimeType).toLowerCase() === 'application/vnd.google-apps.shortcut'; }
function byte(f) { const n = Number(f && f.size); return Number.isFinite(n) ? n : 0; }
// Pesi come li mostrano Drive e il Finder (MB decimali, una cifra): il file per eccesso, il limite per difetto.
function mbTesto(n, limite) { return ((limite ? Math.floor(n / 1e5) : Math.ceil(n / 1e5)) / 10).toFixed(1).replace('.', ',') + ' MB'; }
// Un nome che sembra di una foto o di un video, ma Drive gli ha dato un altro tipo.
function tipoStrano(f) {
  const e = estensione(f && f.name);
  const media = ['jpg', 'jpeg', 'png', 'webp', 'tif', 'tiff', 'avif', 'heic', 'heif'].includes(e) || ESTENSIONI_VIDEO.includes(e);
  return media && !eFoto(f) && !eHeic(f) && !/^video\//i.test(testo(f && f.mimeType)) ? 'Drive non lo riconosce come foto o video (tipo «' + (testo(f.mimeType) || 'sconosciuto') + '»): esportatelo di nuovo' : '';
}
// Impronta corta di un testo (FNV-1a a 32 bit) per ricordare gli avvisi già mandati.
function impronta(s) { let h = 0x811c9dc5; const t = String(s); for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16) + ':' + t.length; }
// Il motivo vero di un errore di Google: n8n 2.x (HTTP Request 4.5) lo mette in error.description e details.description
// (visto nel collaudo: «The user does not have sufficient permissions for this file.»), a volte in details.body, e il
// codice in details.httpCode; error.message è una frase generica di n8n («Forbidden - perhaps check your credentials?»).
function erroreVoce(j) {
  const e = j && j.error;
  if (!e) return '';
  const d = (j && j.details) || {};
  const corpo = d.body && typeof d.body === 'object' ? d.body : null;
  const google = corpo && corpo.error ? (typeof corpo.error === 'string' ? corpo.error : testo(corpo.error.message)) : '';
  const codice = testo(d.httpCode || (typeof e === 'object' && e.httpCode) || '');
  let base = testo(google) || testo(d.description) || (typeof e === 'string' ? e : testo(e.description) || testo(e.message)) || testo(d.message) || JSON.stringify(e);
  if (base.startsWith('<')) base = 'pagina d\'errore di Google';
  return taglia((codice ? 'errore ' + codice + ': ' : '') + base, 200);
}
function cfg() { return $('Config').first().json; }
function modalita() { return norm(cfg().MODALITA) === 'attivo' ? 'attivo' : 'prova'; }
function escHtml(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
// Divide in messaggi Telegram: 4096 unità dopo l'escape HTML, contate in UTF-16 (con le emoji è la misura prudente).
// blocchi = [{ titolo, righe }]; se un blocco continua nel messaggio dopo, il titolo si ripete con «(continua)».
function dividi(testa, blocchi, limite = 3800) {
  const lung = (x) => escHtml(x).length;
  const out = [];
  const aperto = () => cur === testa || cur === testa + ' (continua)';
  let cur = testa;
  for (const b of blocchi) {
    const titolo = taglia(b.titolo || '', 150);
    const righe = (b.righe || []).map((r) => taglia(r, 600));
    if (titolo) {
      if (!aperto() && lung(cur + '\n\n' + titolo + (righe.length ? '\n' + righe[0] : '')) > limite) { out.push(cur); cur = testa + ' (continua)'; }
      cur += '\n\n' + titolo;
    }
    righe.forEach((r, i) => {
      const sep = !titolo && i === 0 ? '\n\n' : '\n';
      if (lung(cur + sep + r) > limite) {
        out.push(cur);
        cur = testa + ' (continua)' + (titolo ? '\n\n' + titolo + ' (continua)\n' : '\n\n') + r;
      } else cur += sep + r;
    });
  }
  out.push(cur);
  return out;
}

// --- Avviso: foglio non letto ---
const c = cfg();
const manuale = $('Avvio a mano').isExecuted;
const e = erroreVoce($input.first().json) || 'errore sconosciuto';
return [{ json: { messaggio: '⚠️ Smista materiale: non riesco a leggere la scheda Clienti del foglio, quindi questo giro non sposta niente.\nMotivo: ' + e + (manuale ? '' : '\nRiprovo da solo al prossimo giro.') } }];

