}
function cfg() { return $('Config').first().json; }
function modalita() { return norm(cfg().MODALITA) === 'attivo' ? 'attivo' : 'prova'; }
function escHtml(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
// Divide in messaggi Telegram: 4096 unità dopo l'escape HTML, contate in UTF-16 (con le emoji è la misura prudente).
// blocchi = [{ titolo, righe }]; se un blocco continua nel messaggio dopo, il titolo si ripete con «(continua)».
function dividi(testa, blocchi, limite = 3800) {
  const lung = (x) => escHtml(x).length;
  const out = [];
  const aperto = () => cur === testa || cur === testa + ' (continua)';
  let cur = testa;
  for (const b of blocchi) {
    const titolo = taglia(b.titolo || '', 150);
    const righe = (b.righe || []).map((r) => taglia(r, 600));
    if (titolo) {
      if (!aperto() && lung(cur + '\n\n' + titolo + (righe.length ? '\n' + righe[0] : '')) > limite) { out.push(cur); cur = testa + ' (continua)'; }
      cur += '\n\n' + titolo;
    }
    righe.forEach((r, i) => {
      const sep = !titolo && i === 0 ? '\n\n' : '\n';
      if (lung(cur + sep + r) > limite) {
        out.push(cur);
        cur = testa + ' (continua)' + (titolo ? '\n\n' + titolo + ' (continua)\n' : '\n\n') + r;
      } else cur += sep + r;
    });
  }
  out.push(cur);
  return out;
}

// --- Esito spostamenti ---
let memoria = null;
try { memoria = $getWorkflowStaticData('global'); } catch (e) { memoria = null; }
const falliti = (memoria && memoria.falliti_smista) || {};
const adesso = Date.now();
const fatti = {};
const ko = [];
const DOVE = { foto: (x) => '→ post', cartella_post: (x) => '→ post (carosello)', cartella_reel: (x) => '→ reel', storia: (x) => '→ storie', video: (x) => '→ reel › ' + x.cartella + ' › ' + x.nuovo_nome };
$input.all().forEach((it, i) => {
  const x = $('Serve una cartella nuova?').itemMatching(i).json;
